"""This file contains generic utility functions used across several GUI test tools
such as Crowbar and the Functional Keypad Interface Test Harness (FkidTh)"""

import logging
import squishtest3 as sq


logger = logging.getLogger(__name__)

# ToT=Yes
def check_checkbox(symbolic_id, checked: bool) -> bool:
    """
    Checks if a given checkbox has already been checked and checks or
    unchecks it depending on the checked bool arg.

    Args:
        checked (bool): True to check checkbox, False to uncheck checkbox

    Returns:
        None
    """
    properties = sq.object.properties(symbolic_id)
    try:
        if checked:
            if properties['checked'] is False:
                sq.mouseClick(symbolic_id)
        else:
            if properties['checked']:
                sq.mouseClick(symbolic_id)

        properties = sq.object.properties(symbolic_id)

        if properties['checked'] == checked:
            return True
        else:
            logger.info("Checkbox failed to check - ", "required - " + #type:ignore
                     checked + ", actual - " + str(properties['checked']))
            return False
    except Exception:
        logging.warning("check_checkbox: not enabled or not found [" + str(symbolic_id) + "]")
        return False


def set_combo_box(symbolic_id, setting):
    combo_box = sq.waitForObject(symbolic_id)
    combo_box.setNativeProperty("Text", setting)
    combo_text = str(combo_box.nativeProperty("Text"))
    if combo_text == setting:
        return True
    else:
        logging.warning("set_combo_box: combo box not set", "required - " + setting + ", actual - " + combo_text)
        return False